  display: flex;
  flex-direction: row;
  width: 100%;
  padding: 20px;
  margin-bottom: 20px;
}

.episode h3 {
  flex: 1;
  min-width: 0;
  max-width: 150px;
  text-align: left;
  margin-bottom: 10px;
}

.episode p {
  margin-bottom: 10px;
  text-align: left;
}

.ethos-badge {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-left: 10px;
}

.episode audio {
  flex: 1;
  min-width: 0;
  box-sizing: border-box;
}

