function renderEpisodes(episodes) {
  const episodesContainer = document.getElementById("episodes");
  episodesContainer.innerHTML = ""; // Clear the container

  episodes.forEach(episode => {
    const episodeDiv = document.createElement("div");
    episodeDiv.className = "episode";
    episodeDiv.innerHTML = `<h3>${escapeHtml(episode.title)}</h3><p>Published: ${escapeHtml(episode.pubDate)}</p><span class="ethos-badge" style="background-color: ${episode.ethos === "pass" ? "green" : episode.ethos === "conflict" ? "red" : "gray"}"></span><audio controls src="${episode.audioUrl}"></audio>`;
    episodesContainer.appendChild(episodeDiv);
  });
  return episodesContainer;
}

