function subscribe() {
  const urlInput = document.querySelector('input[type="text"]');
  const url = urlInput.value;

  fetch(`/api/subscribe?url=${encodeURIComponent(url)}`)
    .then(response => {
      if (!response.ok) {
        throw new Error(`Network response was not ok: ${response.status}`);
      }
      return response.json();
    })
    .then(data => {
      if (data.show) {
        renderEpisodes(data.episodes);
      }
    })
    .catch(error => {
      const errorMessage = `Error subscribing to podcast: ${error.message}`;
      document.getElementById('episodes').textContent = errorMessage;
    });
}

